ALTER TABLE knowledge_document ADD COLUMN issuing_authority VARCHAR(200) NULL,ADD COLUMN effective_from DATE NULL,ADD COLUMN region VARCHAR(64) NULL,ADD COLUMN classification VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'INTERNAL',ADD COLUMN source_name VARCHAR(200) NULL,ADD COLUMN metadata_version BIGINT UNSIGNED NOT NULL DEFAULT 0;
CREATE TABLE knowledge_tag(id BIGINT NOT NULL,name VARCHAR(64) NOT NULL,PRIMARY KEY(id),UNIQUE KEY uk_knowledge_tag_name(name));
CREATE TABLE knowledge_document_tag(document_id BIGINT NOT NULL,tag_id BIGINT NOT NULL,PRIMARY KEY(document_id,tag_id),CONSTRAINT fk_knowledge_document_tag_document FOREIGN KEY(document_id) REFERENCES knowledge_document(id) ON DELETE CASCADE,CONSTRAINT fk_knowledge_document_tag_tag FOREIGN KEY(tag_id) REFERENCES knowledge_tag(id) ON DELETE CASCADE);
CREATE TABLE knowledge_document_version(id BIGINT NOT NULL,document_id BIGINT NOT NULL,version_no BIGINT UNSIGNED NOT NULL,title VARCHAR(200) NOT NULL,metadata_json JSON NOT NULL,content_sha256 CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,created_by BIGINT NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(id),UNIQUE KEY uk_knowledge_document_version(document_id,version_no));
